            return render_table(['format code', 'extension', 'resolution', 'note'], table, extra_gap=1)

        def simplified_codec(f, field):
            assert field in ('acodec', 'vcodec')
            codec = f.get(field, 'unknown')
            if not codec:
                return 'unknown'
            elif codec != 'none':
